package store

import (
	"errors"
	"fmt"
	"regexp"
	"sort"
	"strings"
	"time"
)

// Errors from applying a coupon. ErrNotFound (no such subscription or coupon) is returned as usual.
var (
	ErrCodeTaken            = fmt.Errorf("%w: a coupon has this code", ErrConflict)
	ErrSubscriptionCanceled = errors.New("the subscription is canceled")
	ErrCouponApplied        = errors.New("the subscription already has a coupon")
	ErrCouponExpired        = errors.New("the coupon can no longer be redeemed")
	ErrCouponExhausted      = errors.New("the coupon has no redemptions left")
	ErrCouponCurrency       = errors.New("the coupon's amount is in another currency than the plan")
)

var couponCodeRe = regexp.MustCompile(`^[A-Za-z0-9_-]{3,32}$`)

// CreateCoupon adds a coupon to an organization. Its code is unique in the organization, ignoring case. The caller sets the
// organization and the terms; the store checks them and sets the rest.
func (s *Store) CreateCoupon(c Coupon, now time.Time) (Coupon, error) {
	if !couponCodeRe.MatchString(c.Code) {
		return Coupon{}, invalid("a code is 3 to 32 letters, digits, dashes or underscores")
	}
	switch {
	case (c.PercentOff != 0) == (c.AmountOff != 0):
		return Coupon{}, invalid("a coupon takes percent_off or amount_off, one of them")
	case c.PercentOff != 0 && (c.PercentOff < 1 || c.PercentOff > 100):
		return Coupon{}, invalid("percent_off is 1 to 100")
	case c.AmountOff != 0 && (c.AmountOff < 0 || !c.Currency.Valid()):
		return Coupon{}, invalid("amount_off is a positive amount in a currency Tally bills in")
	}
	if c.PercentOff != 0 {
		c.Currency = ""
	}
	switch c.Duration {
	case CouponOnce, CouponForever:
		if c.DurationInMonths != 0 {
			return Coupon{}, invalid("duration_in_months is only for repeating coupons")
		}
	case CouponRepeating:
		if c.DurationInMonths < 1 || c.DurationInMonths > 36 {
			return Coupon{}, invalid("a repeating coupon lasts 1 to 36 months")
		}
	default:
		return Coupon{}, invalid("a coupon's duration is once, repeating or forever")
	}
	if c.MaxRedemptions < 0 {
		return Coupon{}, invalid("max_redemptions is at least 1")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[c.OrgID]; !ok {
		return Coupon{}, ErrNotFound
	}
	key := couponKey{c.OrgID, strings.ToLower(c.Code)}
	if _, ok := s.couponIDs[key]; ok {
		return Coupon{}, ErrCodeTaken
	}
	c.ID = s.newID("cpn")
	c.CreatedAt = now.UTC()
	c = copyCoupon(c)
	if c.RedeemBy != nil {
		t := c.RedeemBy.UTC()
		c.RedeemBy = &t
	}
	s.coupons[c.ID] = c
	s.couponIDs[key] = c.ID
	return copyCoupon(c), nil
}

// Coupon returns one of an organization's coupons, found by code ignoring case.
func (s *Store) Coupon(orgID, code string) (Coupon, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	id, ok := s.couponIDs[couponKey{orgID, strings.ToLower(code)}]
	if !ok {
		return Coupon{}, false
	}
	return copyCoupon(s.coupons[id]), true
}

// Coupons returns an organization's coupons, oldest first.
func (s *Store) Coupons(orgID string) []Coupon {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Coupon{}
	for _, c := range s.coupons {
		if c.OrgID == orgID {
			out = append(out, copyCoupon(c))
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

// CouponRedemptions counts the subscriptions of an organization that have the coupon with this code.
func (s *Store) CouponRedemptions(orgID, code string) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	c, ok := s.couponIDs[couponKey{orgID, strings.ToLower(code)}]
	if !ok {
		return 0
	}
	return s.redemptions(orgID, s.coupons[c].Code)
}

// redemptions counts the subscriptions that have the coupon with this exact code. The caller holds the lock.
func (s *Store) redemptions(orgID, code string) int {
	n := 0
	for _, sub := range s.subs {
		if sub.OrgID == orgID && sub.Coupon == code {
			n++
		}
	}
	return n
}

// ApplyCoupon applies the coupon with this code to a subscription at now, which is the redemption time. It refuses a
// canceled subscription, one that already has a coupon, an expired coupon, one with no redemptions left, and an amount
// coupon in another currency than the subscription's plan. The checks and the change happen under one lock, so a coupon
// with a limit is never redeemed more often than it allows.
func (s *Store) ApplyCoupon(orgID, subID, code string, now time.Time) (Subscription, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	sub, ok := s.subs[subID]
	if !ok || sub.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	id, ok := s.couponIDs[couponKey{orgID, strings.ToLower(code)}]
	if !ok {
		return Subscription{}, ErrNotFound
	}
	c := s.coupons[id]
	switch {
	case sub.Status == Canceled:
		return Subscription{}, ErrSubscriptionCanceled
	case sub.Coupon != "":
		return Subscription{}, ErrCouponApplied
	case c.RedeemBy != nil && now.After(*c.RedeemBy):
		return Subscription{}, ErrCouponExpired
	case c.MaxRedemptions > 0 && s.redemptions(orgID, c.Code) >= c.MaxRedemptions:
		return Subscription{}, ErrCouponExhausted
	case c.AmountOff != 0 && c.Currency != s.plans[sub.PlanID].Currency:
		return Subscription{}, ErrCouponCurrency
	}
	t := now.UTC()
	sub.Coupon, sub.CouponRedeemedAt = c.Code, &t
	s.subs[subID] = sub
	return copySub(sub), nil
}

func copyCoupon(c Coupon) Coupon {
	if c.RedeemBy != nil {
		t := *c.RedeemBy
		c.RedeemBy = &t
	}
	return c
}

package store

import (
	"errors"
	"fmt"
	"regexp"
	"sort"
