// couponFor returns the coupon that discounts an invoice of sub, created at now for a period starting at start, if one
// applies. The coupon applies to invoices created after it was applied: once, only the first of them; repeating, those whose
// period starts less than its duration in months after the redemption; forever, all of them. An amount coupon does not apply
// to a plan in another currency than the coupon's.
func (s *Service) couponFor(sub store.Subscription, plan store.Plan, start, now time.Time) (store.Coupon, bool, error) {
	if sub.Coupon == "" || sub.CouponRedeemedAt == nil || !now.After(*sub.CouponRedeemedAt) {
		return store.Coupon{}, false, nil
	}
	c, ok := s.Store.Coupon(sub.OrgID, sub.Coupon)
	if !ok {
		return store.Coupon{}, false, store.ErrNotFound
	}
	if c.AmountOff != 0 && c.Currency != plan.Currency {
		return store.Coupon{}, false, nil
	}
	redeemed := *sub.CouponRedeemedAt
	switch c.Duration {
	case store.CouponOnce:
		for _, inv := range s.Store.ListInvoices(sub.OrgID, store.InvoiceFilter{SubscriptionID: sub.ID}) {
			if inv.Coupon == c.Code {
				return store.Coupon{}, false, nil
			}
		}
	case store.CouponRepeating:
		if !start.Before(redeemed.AddDate(0, c.DurationInMonths, 0)) {
			return store.Coupon{}, false, nil
		}
	}
	return c, true, nil
}

