package api

import (
	"errors"
	"net/http"
	"time"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// couponView is a coupon as the API shows it: with how many subscriptions have it.
type couponView struct {
	store.Coupon
	TimesRedeemed int `json:"times_redeemed"`
}

func (s *Server) couponView(c store.Coupon) couponView {
	return couponView{Coupon: c, TimesRedeemed: s.store.CouponRedemptions(c.OrgID, c.Code)}
}

func couponKeyOf(c store.Coupon) cursor { return cursor{T: c.CreatedAt, ID: c.ID} }

// listCoupons lists the organization's coupons, oldest first.
func (s *Server) listCoupons(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	coupons := s.store.Coupons(p.OrgID)
	views := make([]couponView, 0, len(coupons))
	for _, c := range coupons {
		views = append(views, s.couponView(c))
	}
	items, next := pageOf(views, func(v couponView) cursor { return couponKeyOf(v.Coupon) }, pg)
	writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
}

// createCoupon adds a coupon: {"code", "percent_off" or "amount_off" (a string in major units, with "currency"), "duration",
// "duration_in_months" (repeating only), "max_redemptions" (optional), "redeem_by" (optional, RFC 3339)}.
func (s *Server) createCoupon(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Code             string               `json:"code"`
		PercentOff       *int                 `json:"percent_off"`
		AmountOff        *string              `json:"amount_off"`
		Currency         money.Currency       `json:"currency"`
		Duration         store.CouponDuration `json:"duration"`
		DurationInMonths *int                 `json:"duration_in_months"`
		MaxRedemptions   *int                 `json:"max_redemptions"`
		RedeemBy         *string              `json:"redeem_by"`
	}
	if !decode(w, r, &in) {
		return
	}
	c := store.Coupon{OrgID: p.OrgID, Code: in.Code, Currency: in.Currency, Duration: in.Duration}
	if (in.PercentOff != nil) == (in.AmountOff != nil) {
		writeError(w, http.StatusUnprocessableEntity, "invalid", "a coupon takes percent_off or amount_off, one of them")
		return
	}
	if in.PercentOff != nil {
		c.PercentOff = *in.PercentOff
	}
	if in.AmountOff != nil {
		amount, err := money.ParseMajor(*in.AmountOff, in.Currency)
		if err != nil {
			writeError(w, http.StatusUnprocessableEntity, "invalid", "amount_off is an amount in major units, like \"12.50\", and a currency")
			return
		}
		c.AmountOff = amount
	}
	if in.DurationInMonths != nil {
		if in.Duration != store.CouponRepeating {
			writeError(w, http.StatusUnprocessableEntity, "invalid", "duration_in_months is only for repeating coupons")
			return
		}
		c.DurationInMonths = *in.DurationInMonths
	}
	if in.MaxRedemptions != nil {
		if *in.MaxRedemptions < 1 {
			writeError(w, http.StatusUnprocessableEntity, "invalid", "max_redemptions is at least 1")
			return
		}
		c.MaxRedemptions = *in.MaxRedemptions
	}
	if in.RedeemBy != nil {
		t, err := time.Parse(time.RFC3339, *in.RedeemBy)
		if err != nil {
			writeError(w, http.StatusUnprocessableEntity, "invalid", "redeem_by is a time in RFC 3339 format")
			return
		}
		c.RedeemBy = &t
	}
	created, err := s.store.CreateCoupon(c, s.clock.Now())
	if errors.Is(err, store.ErrCodeTaken) {
		writeError(w, http.StatusConflict, "code_taken", "a coupon with this code already exists")
		return
	}
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, s.couponView(created))
}

func (s *Server) getCoupon(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	c, ok := s.store.Coupon(p.OrgID, r.PathValue("code"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such coupon")
		return
	}
	writeJSON(w, http.StatusOK, s.couponView(c))
}

// applyCoupon applies a coupon to a subscription: {"code"}. The subscription shows the coupon from then on.
func (s *Server) applyCoupon(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Code string `json:"code"`
	}
	if !decode(w, r, &in) {
		return
	}
	sub, err := s.store.ApplyCoupon(p.OrgID, r.PathValue("id"), in.Code, s.clock.Now())
	switch {
	case errors.Is(err, store.ErrSubscriptionCanceled):
		writeError(w, http.StatusConflict, "subscription_canceled", err.Error())
		return
	case errors.Is(err, store.ErrCouponApplied):
		writeError(w, http.StatusConflict, "coupon_already_applied", err.Error())
		return
	case errors.Is(err, store.ErrCouponExpired):
		writeError(w, http.StatusUnprocessableEntity, "coupon_expired", err.Error())
		return
	case errors.Is(err, store.ErrCouponExhausted):
		writeError(w, http.StatusUnprocessableEntity, "coupon_exhausted", err.Error())
		return
	case errors.Is(err, store.ErrCouponCurrency):
		writeError(w, http.StatusUnprocessableEntity, "currency_mismatch", err.Error())
		return
	case err != nil:
		s.storeError(w, err)
		return
	}
	s.publish(r.Context(), p.OrgID, "subscription.updated", sub)
	writeJSON(w, http.StatusOK, sub)
}

