func TestComputeWithCoupon(t *testing.T) {
	lines := []store.Line{{Description: "x", Quantity: 1, UnitAmount: 1000}}
	// A coupon's terms give the discount, not DiscountPercent; tax is charged on what remains.
	percent := Compute(store.Invoice{Lines: lines, DiscountPercent: 10, TaxRateBP: 1000, Coupon: "P", CouponPercentOff: 25})
	if percent != (Totals{Subtotal: 1000, Discount: 250, Tax: 75, Total: 825}) {
		t.Fatalf("percent coupon: %+v", percent)
	}
	amount := Compute(store.Invoice{Lines: lines, TaxRateBP: 1000, Coupon: "A", CouponAmountOff: 300})
	if amount != (Totals{Subtotal: 1000, Discount: 300, Tax: 70, Total: 770}) {
		t.Fatalf("amount coupon: %+v", amount)
	}
	// An amount coupon never takes more than the subtotal.
	big := Compute(store.Invoice{Lines: lines, TaxRateBP: 1000, Coupon: "B", CouponAmountOff: 5000})
	if big != (Totals{Subtotal: 1000, Discount: 1000, Tax: 0, Total: 0}) {
		t.Fatalf("large amount coupon: %+v", big)
	}
}

