package api_test

import (
	"context"
	"net/http"
	"strings"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

// couponJSON is a coupon as the API answers it.
type couponJSON struct {
	store.Coupon
	TimesRedeemed int `json:"times_redeemed"`
}

// invoiceJSON is an invoice as the API answers it, with its totals.
type invoiceJSON struct {
	store.Invoice
	Subtotal, Discount, Tax, Total int64
}

func invoicesOf(e *apitest.Env, sub store.Subscription) []invoiceJSON {
	e.T.Helper()
	var page struct {
		Items []invoiceJSON `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?subscription_id="+sub.ID, e.Acme.Key, nil, &page)
	return page.Items
}

func TestCouponCreate(t *testing.T) {
	e := apitest.New(t)
	var c couponJSON
	e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "SPRING_10", "percent_off": 10, "duration": "forever"}, &c)
	if c.Code != "SPRING_10" || c.PercentOff != 10 || c.AmountOff != 0 || c.Duration != store.CouponForever || c.TimesRedeemed != 0 || c.OrgID != e.Acme.ID {
		t.Fatalf("coupon = %+v", c)
	}
	// amount_off is read in major units and kept in minor units.
	e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "fifty-off", "amount_off": "12.50", "currency": "USD",
		"duration": "repeating", "duration_in_months": 3, "max_redemptions": 5, "redeem_by": "2026-06-30T00:00:00Z"}, &c)
	if c.AmountOff != 1250 || c.Currency != "USD" || c.DurationInMonths != 3 || c.MaxRedemptions != 5 || c.RedeemBy == nil ||
		!c.RedeemBy.Equal(time.Date(2026, time.June, 30, 0, 0, 0, 0, time.UTC)) {
		t.Fatalf("coupon = %+v", c)
	}
	// Codes are unique in an organization, ignoring case. Another organization may use the same code.
	if r := e.Do("POST", "/v1/coupons", e.Acme.Key, map[string]any{"code": "spring_10", "percent_off": 5, "duration": "once"}); r.Code != http.StatusConflict || r.Map(t)["error"] != "code_taken" {
		t.Fatalf("taken: %s", r)
	}
