		e.MustDo(http.StatusCreated, "POST", "/v1/coupons", org.Key, body, nil)
	}
	apply := func(sub store.Subscription, key, code string) *apitest.Response {
		return e.Do("POST", "/v1/subscriptions/"+sub.ID+"/coupon", key, map[string]any{"code": code})
	}

	mk(e.Acme, map[string]any{"code": "SAVE10", "percent_off": 10, "duration": "forever", "max_redemptions": 1})
	first := newSub()
	var applied store.Subscription
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+first.ID+"/coupon", e.Acme.Key, map[string]any{"code": "save10"}, &applied)
	if applied.Coupon != "SAVE10" || applied.CouponRedeemedAt == nil || !applied.CouponRedeemedAt.Equal(apitest.Start) {
		t.Fatalf("applied = %+v", applied)
	}
	if r := apply(first, e.Acme.Key, "SAVE10"); r.Code != http.StatusConflict || r.Map(t)["error"] != "coupon_already_applied" {
		t.Fatalf("second coupon on one subscription: %s", r)
	}
	second := newSub()
	if r := apply(second, e.Acme.Key, "SAVE10"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "coupon_exhausted" {
		t.Fatalf("redemption limit: %s", r)
	}
	var got couponJSON
	e.MustDo(http.StatusOK, "GET", "/v1/coupons/SAVE10", e.Acme.Key, nil, &got)
	if got.TimesRedeemed != 1 {
		t.Fatalf("times_redeemed = %d, want 1", got.TimesRedeemed)
	}

	mk(e.Globex, map[string]any{"code": "GLOBEX_ONLY", "percent_off": 10, "duration": "forever"})
	if r := apply(second, e.Acme.Key, "GLOBEX_ONLY"); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("another organization's coupon: %s", r)
	}
	if r := apply(second, e.Acme.Key, "nothing"); r.Code != http.StatusNotFound {
		t.Fatalf("missing coupon: %s", r)
	}
	if r := apply(second, e.Globex.Key, "SAVE10"); r.Code != http.StatusNotFound {
		t.Fatalf("another organization's subscription: %s", r)
	}

	mk(e.Acme, map[string]any{"code": "EURO5", "amount_off": "5.00", "currency": "EUR", "duration": "forever"})
	if r := apply(newSub(), e.Acme.Key, "EURO5"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "currency_mismatch" {
		t.Fatalf("currency: %s", r)
	}

	mk(e.Acme, map[string]any{"code": "OPEN", "percent_off": 5, "duration": "forever"})
	canceled := newSub()
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+canceled.ID+"/cancel", e.Acme.Key, nil, nil)
	if r := apply(canceled, e.Acme.Key, "OPEN"); r.Code != http.StatusConflict || r.Map(t)["error"] != "subscription_canceled" {
		t.Fatalf("canceled: %s", r)
	}

	// A coupon can be redeemed up to its redeem_by time, not after it.
	redeemBy := apitest.Start.Add(24 * time.Hour).Format(time.RFC3339)
	mk(e.Acme, map[string]any{"code": "LATE", "percent_off": 5, "duration": "forever", "redeem_by": redeemBy})
	mk(e.Acme, map[string]any{"code": "LATER", "percent_off": 5, "duration": "forever", "redeem_by": redeemBy})
	if r := apply(newSub(), e.Acme.Key, "LATE"); r.Code != http.StatusOK {
		t.Fatalf("at redeem_by: %s", r)
	}
	e.Clock.Set(apitest.Start.Add(25 * time.Hour))
	if r := apply(newSub(), e.Acme.Key, "LATER"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "coupon_expired" {
		t.Fatalf("after redeem_by: %s", r)
	}
}

func TestCouponsDiscountRenewals(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	mk := func(body map[string]any) {
		e.MustDo(http.StatusCreated, "POST", "/v1/coupons", e.Acme.Key, body, nil)
	}
	// newSub starts a subscription at the start of the test, and applies the coupon (if any) at once.
	newSub := func(discount int, coupon string) store.Subscription {
		var sub store.Subscription
		e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": c.ID, "plan_id": p.ID, "discount_percent": discount}, &sub)
		if coupon != "" {
			e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/coupon", e.Acme.Key, map[string]any{"code": coupon}, &sub)
		}
		return sub
	}
	// expect checks invoice idx of a subscription: its coupon, discount, the subscription's discount percent and total.
	expect := func(sub store.Subscription, idx int, coupon string, discount int64, percent int, total int64) {
		t.Helper()
		invs := invoicesOf(e, sub)
		if len(invs) <= idx {
			t.Fatalf("%s has %d invoices, want invoice %d", sub.ID, len(invs), idx)
		}
		got := invs[idx]
		if got.Coupon != coupon || got.Discount != discount || got.DiscountPercent != percent || got.Total != total {
			t.Errorf("%s invoice %d: coupon %q discount %d (%d%%) total %d; want %q %d (%d%%) %d",
				sub.ID, idx, got.Coupon, got.Discount, got.DiscountPercent, got.Total, coupon, discount, percent, total)
		}
	}
	renewAt := func(months int) {
		t.Helper()
		e.Clock.Set(apitest.Start.AddDate(0, months, 0))
		if _, err := e.Subs.RenewDue(context.Background()); err != nil {
			t.Fatal(err)
		}
	}

	mk(map[string]any{"code": "HALF", "percent_off": 50, "duration": "repeating", "duration_in_months": 2})
	mk(map[string]any{"code": "FIVE", "amount_off": "5.00", "currency": "USD", "duration": "forever"})
	mk(map[string]any{"code": "BIG", "amount_off": "50.00", "currency": "USD", "duration": "forever"})
	mk(map[string]any{"code": "ONCE25", "percent_off": 25, "duration": "once"})
	mk(map[string]any{"code": "REP2B", "percent_off": 50, "duration": "repeating", "duration_in_months": 2})

	repeating := newSub(0, "HALF")
	forever := newSub(0, "FIVE")
	bigAmount := newSub(0, "BIG")
	once := newSub(10, "ONCE25")
	expiring := newSub(10, "REP2B")

	renewAt(1)
	expect(repeating, 1, "HALF", 1000, 0, 1000)
	expect(forever, 1, "FIVE", 500, 0, 1500)
	expect(bigAmount, 1, "BIG", 2000, 0, 0)
	// A coupon takes the place of the subscription's discount_percent on the invoices it applies to.
	expect(once, 1, "ONCE25", 500, 0, 1500)
	expect(expiring, 1, "REP2B", 1000, 0, 1000)

	renewAt(2)
	// The repeating coupon covers the periods starting less than two months after it was applied, so this one is not discounted.
	expect(repeating, 2, "", 0, 0, 2000)
	expect(forever, 2, "FIVE", 500, 0, 1500)
	expect(bigAmount, 2, "BIG", 2000, 0, 0)
	// The once coupon is gone, so the subscription's own 10% applies again.
	expect(once, 2, "", 200, 10, 1800)
	expect(expiring, 2, "", 200, 10, 1800)
}

